import{_ as a,o as e,a as l,b as i}from"./app.C41L12d5.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"高阶API","link":"/api/SIMD-API/adv_api/adv_api"},{"text":"矩阵计算","link":"/api/SIMD-API/adv_api/cube_compute/cube_compute"},{"text":"Matmul核函数（Kernel）侧接口","link":"/api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/Matmul_Kernel"},{"text":"REGIST_MATMUL_OBJ","link":"/api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/REGIST_MATMUL_OBJ"}]},"headers":[],"relativePath":"api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/REGIST_MATMUL_OBJ.md","filePath":"api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/REGIST_MATMUL_OBJ.md","outlineHeaders":[{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1787050286000}'),n={name:"api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/REGIST_MATMUL_OBJ.md"};function r(p,t,c,s,o,_){return e(),l("div",null,[...t[0]||(t[0]=[i(`<div><article class="markdown-body"><h1>REGIST_MATMUL_OBJ</h1><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>初始化Matmul对象。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>REGIST_MATMUL_OBJ(tpipe, workspace, ...)
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>tpipe</td><td>输入</td><td>Tpipe对象。</td></tr><tr><td>workspace</td><td>输入</td><td>系统workspace指针。</td></tr><tr><td>...</td><td>输入</td><td>可变参数，传入Matmul对象和与之对应的Tiling结构，要求Tiling结构的数据类型为<a href="../Matmul_Tiling/TCubeTiling_struct.html#tcubetiling-struct">TCubeTiling结构</a>。<br><br>Tiling参数可以通过Host侧<a href="../Matmul_Tiling/GetTiling.html">GetTiling</a>接口获取，并传递到kernel侧使用。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>在分离模式中，本接口必须在<a href="../../../basic_api/resource_management/TPipe/InitBuffer.html">InitBuffer</a>接口前调用。</li><li>在程序中，最多支持定义4个Matmul对象。</li><li>在Matmul的内部实现中使用了<a href="../../../basic_api/sync_control/inter_core_sync/CrossCoreSetFlag_ISASI.html">CrossCoreSetFlag</a>和<a href="../../../basic_api/sync_control/inter_core_sync/CrossCoreWaitFlag_ISASI.html">CrossCoreWaitFlag</a>进行核间同步控制，因此开发者同时使用CrossCoreSetFlag（或CrossCoreWaitFlag）和Matmul时，需注意避免核间同步flagId冲突。Matmul高阶API内部占用的flagId范围与定义的Matmul对象数目相关。假设定义了N个Matmul对象，则Matmul高阶API内部占用的flagId范围为[0, 2 * N - 1]。Matmul最多支持定义4个对象，此时flagId占用范围为[0, 7]。</li><li>当代码中只有一个Matmul对象时，本接口可以不传入tiling参数，通过<a href="Init.html">Init</a>接口单独传入tiling参数。</li><li>当代码中有多个Matmul对象时，必须满足Matmul对象与其tiling参数一一对应，依次传入，具体方式请参考调用示例。</li><li>在分离模式中，调用本接口后，AIC核不会主动执行接口，仅在AIV核执行到下述接口后，才会触发AIC核的执行，其他接口则不会在AIC核上执行。 <ul><li><a href="Matmul_Kernel.html">Matmul核函数（Kernel）侧接口</a>。</li><li><a href="../../../basic_api/cube_compute_ISASI/cube_compute_load/DataCopy_GMToL1_continuous.html">DataCopy(GMToL1连续数据搬运)</a>、<a href="../../../basic_api/cube_compute_ISASI/cube_compute_load/DataCopy_GMToL1_highdim_split.html">DataCopy(GMToL1高维切分数据搬运)</a>、<a href="../../../basic_api/cube_compute_ISASI/cube_compute_load/DataCopy_GMToL1_ND2NZ.html">DataCopy(GMToL1随路转换-ND2NZ搬运)</a>。</li></ul></li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>Tpipe pipe;
// 推荐：初始化单个matmul对象，传入tiling参数
REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm, &amp;tiling);
// 推荐：初始化多个matmul对象，传入对应的tiling参数
REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm1, mm1tiling, mm2, mm2tiling, mm3, mm3tiling, mm4, mm4tiling);
// 初始化单个matmul对象，未传入tiling参数。注意，该场景下需要使用Init接口单独传入tiling参数。这种方式将matmul对象的初始化和tiling的设置分离，比如，Tiling可变的场景，可通过这种方式多次对Tiling进行重新设置
REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm);
mm.Init(&amp;tiling);
</code></pre></div></article></div>`,1)])])}const d=a(n,[["render",r]]);export{m as __pageData,d as default};
